"ctx": "De president van de ECB kondigt een renteverlaging aan naar 0,25 procent om de deflatie in Europa tegen te gaan. Als gevolg van de renteverlaging door de ECB verlagen de Nederlandse banken op hun beurt de rente voor hun klanten.",
