"ctx": "Als gevolg van het tekort aan specialiteitenkoks dreigen de loonkosten van Aziatische restaurants hoog op te lopen. Om dit te voorkomen willen de Aziatische restaurants koks uit Azië laten overkomen. Dit wordt echter bemoeilijkt door de Wet arbeid vreemdelingen (WAV). In de WAV staan strenge voorwaarden voor het laten werken van werknemers uit landen waarmee Nederland geen vrij verkeer van arbeid heeft afgesproken. Een gevolg van de WAV is dat de opwaartse druk op de lonen van specialiteitenkoks blijft bestaan.",
"q": "Verklaar dit gevolg van de WAV op de loonontwikkeling van\n specialiteitenkoks.",
