"ctx": "Uit een krant, 2019: De Europese Centrale Bank (ECB) pakt flink uit met een nóg lagere rente om de bestedingen te stimuleren. De economie heeft het hard nodig, vindt de ECB. Het is de taak van een centrale bank om er alles aan te doen om de inflatie op een gewenst stabiel niveau (2%) te houden. De ECB wil de inflatie op dit moment stimuleren, om een veiligheidsmarge te hebben tegen de mogelijke risico's van deflatie.",
"q": "Leg uit dat verwachte deflatie een negatieve invloed heeft op de\n economische groei.",
"model": "Een voorbeeld van een juist antwoord is:\n• Consumenten verwachten (verdere) prijsdaling en stellen hun aankopen uit, en (1p)\n• hierdoor dalen de bestedingen en daalt de productie. Dit leidt tot een lagere economische groei (1p)\nOpmerking De cursief gedrukte aspecten moeten genoemd of verwoord zijn voor toekenning van scorepunten.",
