"ctx": "Een analist van het ministerie van economische zaken benadrukt dat economische groei van invloed is op de effectiviteit van het overheidsbeleid om de vraag naar gas van gezinnen en bedrijven te verminderen. De analist doet drie uitspraken: - Uitspraak 1: Economische groei kan enerzijds tot meer gasverbruik en anderzijds tot minder gasverbruik leiden. - Uitspraak 2: Economische groei maakt het voor de overheid makkelijker om subsidies te financieren. - Uitspraak 3: Subsidies op energiezuinige productietechnologieën en de verhoging van de energiebelasting op gasverbruik van gezinnen en bedrijven, hebben zelf ook weer effect op de economische groei van het land.",
"q": "Leg uitspraak 3 uit. Betrek in je antwoord een positief effect en een\n negatief effect.",
"model": "Een voorbeeld van een juist antwoord is:\n• positief effect op de economische groei: (De vraag naar en) de productie van energiezuinige technologie stijgt (door de subsidie) hetgeen een positief effect kan hebben op (de groei van) het bbp / de productie (1p)\n• negatief effect op de economische groei: Bedrijven krijgen te maken met hogere kosten (door de verhoging van energiebelasting). Dit kan ten koste gaan van de winst. Hierdoor kunnen de investeringen afnemen, hetgeen een negatief effect kan hebben op (de groei van) het bbp / de productie of: Gezinnen kunnen te maken krijgen met hogere energieuitgaven (door de verhoging van energiebelasting). Hierdoor kan het besteedbaar inkomen voor overige consumptiegoederen afnemen, hetgeen een negatief effect kan hebben op (de groei van) het bbp (1p)\nOpmerking Als bij de beantwoording van het positieve en het negatieve effect productie of bbp niet genoemd is dan maximaal een scorepunt toekennen.",
