"q": "Maak van de onderstaande zinnen een economisch juiste tekst.\n\n- Bij medicijnen zie je in het algemeen dat de vraag …(1)… is. - Ook bij daling van het inkomen zal de vraag naar het medicijn\n nauwelijks dalen. Er is hier sprake van een …(2)… goed. Kies uit: bij (1) prijselastisch / prijsinelastisch bij (2) noodzakelijk / inferieur",
