"ctx": "Kate Miller zoekt naar opties om ervoor te zorgen dat dit medicijn betaalbaar blijft. Zij stelt de volgende maatregelen voor: A: het vaststellen van een maximumprijs door de overheid B: het sneller laten aflopen van het patent op het medicijn",
