"model": "Een voorbeeld van een juist antwoord is:\n• Maatregel A: Het instellen van een maximumprijs zal leiden tot een lagere prijs mits de maximale prijs die de overheid vaststelt lager is dan de prijs bij maximale winst (1p)\n• Maatregel B: Na afloop van het patent kunnen andere aanbieders het medicijn ook aanbieden en door de toegenomen concurrentie kan de prijs dalen (omdat Fluid niet langer monopolist/prijszetter is, en omdat de afwezigheid van toetredingsbarrières het mogelijk maakt dat andere fabrikanten het medicijn met lagere kosten kunnen fabriceren) (1p)",
