"nr": 22,
"ctx": "Fluid is geen voorstander van beide maatregelen. De directeur van Fluid stelt dat (te) lage winsten op nieuw te ontwikkelen medicijnen in de toekomst gevolgen kunnen hebben voor de welvaart. Fluid verwijst daarbij naar de Human Development Index. De Human Development Index (HDI) is een welvaartsindex van de Verenigde Naties die voornamelijk armoede, analfabetisme, onderwijs en levensverwachting in een bepaald land meet.",
