"ctx": "Barbara Berends is onderhandelaar van de supermarktketens, en Jacco Jansen is onderhandelaar van de vakbond. Samen bespreken zij de consequenties van de loonstijging die door de vakbond geëist is. De onderhandelaar van de werkgever vindt de looneis te hoog. Barbara Berends: “U moet zich realiseren dat een loonkostenstijging van 3,5% binnen ons bedrijf, waar de loonkosten 40% van de totale kosten uitmaken, zal leiden tot een productiekostenstijging van 1,4%. De supermarktketens kunnen deze hoge looneis niet betalen.” Jacco Jansen reageert met de volgende uitspraken: 1 U spreekt over de nominale productiekostenstijging, maar de reële productiekostenstijging is lager. 2 Bovendien leidt de gestegen arbeidsproductiviteit tot lagere productiekosten. 3 En u moet zich realiseren dat de omzet bij supermarkten toch zal stijgen, aangezien is gebleken dat de vraag naar goederen uit de supermarkt prijsinelastisch is.",
