"ctx": "De directie van Snel wil Sprinter een prijsvoorstel doen van € 3.700 per speedpedelec. Een deskundige op het gebied van ultimatumspellen waarschuwt: “Snel kan beter een hoger bod doen aan Sprinter, want de praktijk leert dat zo’n laag bod toch vaak geweigerd wordt, ondanks dat beide bedrijven dan niets ontvangen.”",
