"ctx": "Als gevolg van de lage dekkingsgraad is de kans groot dat de huidige en toekomstige pensioenuitkeringen moeten worden verlaagd.",
"q": "Geef een verklaring dat verlaging van de pensioenuitkeringen de\n bestedingen van ouderen kan verlagen.",
"model": "Een voorbeeld van een juist antwoord is: Een verlaging van de pensioenuitkeringen betekent een daling van het inkomen van gepensioneerden/ouderen, waardoor hun bestedingen / uitgaven kunnen afnemen.",
