"ctx": "Bij het besluit om in te grijpen in de markt, heeft de overheid een afweging gemaakt tussen de belangen van verschillende groepen in de samenleving. Een econoom stelt dat twee groepen financieel nadeel ondervinden van de ingreep: de kopers van de cashewnoten en de burgers van het land.",
"q": "Leg met behulp van het begrip consumentensurplus uit dat de\n minimumprijs financieel nadelig is voor de kopers van cashewnoten.",
"model": "Een voorbeeld van een juist antwoord is:\n• Het consumentensurplus is gelijk aan het verschil tussen de betalingsbereidheid en de te betalen prijs, en (1p)\n• dit verschil wordt kleiner doordat de kopers een hogere prijs (dan de evenwichtsprijs) moeten betalen (en dit is een nadeel voor de kopers). (1p)\nof via verwijzing naar bron 1:\n• Het consumentensurplus verandert door de minimumprijs van EKG naar HKI, en (1p)\n• dit betekent dat het consumentensurplus afneemt (en dit is een nadeel voor de kopers). (1p)",
