"ctx": "Bij het besluit om in te grijpen in de markt, heeft de overheid een afweging gemaakt tussen de belangen van verschillende groepen in de samenleving. Een econoom stelt dat twee groepen financieel nadeel ondervinden van de ingreep: de kopers van de cashewnoten en de burgers van het land.",
