"ctx": "Nederland heeft een wettelijk minimumuurloon voor alle werknemers van 15 jaar en ouder. In een talkshow debatteren twee economen over de gevolgen van het verhogen van dit minimumuurloon. Econoom 2: ‘Een hoger minimumuurloon kan leiden tot een verslechtering van de Nederlandse internationale concurrentiepositie’. Econoom 1: ‘Een hoger minimumuurloon kan leiden tot meer economische groei’.",
"q": "Leg de uitspraak van econoom 2 uit.",
"model": "Een juist antwoord bevat in relatie tot de context:\n• Een correcte uitleg over het verband tussen loonkosten en loonkosten per product. (1p)\n• Een correcte uitleg over het verband tussen loonkosten per product en de internationale concurrentiepositie. (1p)\nEen voorbeeld van een juist antwoord is:\n• Door de hogere minimumuurlonen zullen de kosten voor bedrijven toenemen. Hierdoor zullen (bij gelijkblijvende arbeidsproductiviteit) de (loon)kosten per product stijgen. (1p)\n• Deze hogere kosten worden doorberekend in de prijs, waardoor Nederland duurder wordt voor het buitenland en de internationale concurrentiepositie dus verslechtert. (1p)",
