"ctx": "Uit een krant: Afgelopen maand daalden de aandelenkoersen in de Verenigde Staten (VS) zeer sterk. In één week zelfs gemiddeld met 8,5 procent. Deze daling wordt door een deel van de beursanalisten gezien als een ‘gezonde’ correctie. Andere analisten maken zich juist zorgen over het effect dat deze daling heeft op het consumentenvertrouwen. De aandelenkoers wordt bepaald door vraag en aanbod van aandelen op de aandelenmarkt.",
