"q": "Beargumenteer dat FC Forward een sterke onderhandelingspositie heeft\n ten opzichte van de verhuurder.",
"model": "Een voorbeeld van een juist antwoord is: Het is voor de verhuurder niet mogelijk om een andere huurder te vinden. (Daarom heeft FC Forward een sterke onderhandelingspositie.)",
