"q": "Gebruik tabel 2. FC Forward kiest het scenario dat de hoogste totale omzet oplevert.\nKiest de club voor scenario 1 of scenario 2? Verklaar je antwoord met\n behulp van een berekening.\n(De figuur of tabel staat in het examen zelf. Die zit nog niet in de app: pak het examen erbij.)",
