"ctx": "Econoom B is tegenstander van het verlagen van de staatsschuld. De econoom stelt: a De rente op een staatslening is nu −0,4%, terwijl de inflatie 2,8% is. Niet aflossen dus\\! b In de toekomst zal de beroepsbevolking krimpen, waardoor er te weinig personeel zal zijn op de arbeidsmarkt. Door niet af te lossen houdt de overheid geld over voor het financieren van innovatie projecten.",
"q": "Leg stelling a uit. Maak hierbij gebruik van het begrip reële rente.",
"model": "Een voorbeeld van een juist antwoord is:\n• De inflatie is hoger dan de nominale rente, dus de reële rente is negatief. (1p)\n• (Dit betekent dat de koopkracht / reële waarde van een schuld lager wordt) waardoor lenen / het aangaan van schulden financieel gunstig is. (1p)",
